import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.7w-lhQN6.js";const k=JSON.parse('{"title":"대시보드","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/dashboard.md","filePath":"ko/guide/dashboard.md","lastUpdated":1793550481000}'),d={name:"ko/guide/dashboard.md"};function n(o,a,r,h,p,l){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="대시보드" tabindex="-1">대시보드 <a class="header-anchor" href="#대시보드" aria-label="Permalink to &quot;대시보드&quot;">​</a></h1><p>이 문서를 끝내면 로컬 웹 대시보드를 빌드하고 실행하는 방법과 거기서 무엇을 기대할 수 있는지 알게 된다. <strong>대시보드는 동결됐다.</strong> 코드와 테스트는 저장소에 남아 있지만 새 기능은 더 이상 여기 들어가지 않는다. VS Code 사이드바(<code>Cost × Usage Matrix</code>와 <code>Setup Status</code> 뷰)가 그 역할을 흡수했기 때문이다. 동결 시점 기준으로는 여전히 동작한다.</p><h2 id="vs-code-사이드바-대신-언제-쓰는가" tabindex="-1">VS Code 사이드바 대신 언제 쓰는가 <a class="header-anchor" href="#vs-code-사이드바-대신-언제-쓰는가" aria-label="Permalink to &quot;VS Code 사이드바 대신 언제 쓰는가&quot;">​</a></h2><p>이미 <a href="/MCPLens/ko/guide/vscode-extension">VS Code 확장</a>을 쓰고 있다면 사이드바가 유지보수되는 경로이고 같은 비용 × 사용량 매트릭스를 다룬다. 대시보드는 VS Code를 열지 않고 브라우저로만 보고 싶을 때, 예를 들어 CLI 전용 경로로 작업할 때만 쓴다.</p><h2 id="빌드와-실행" tabindex="-1">빌드와 실행 <a class="header-anchor" href="#빌드와-실행" aria-label="Permalink to &quot;빌드와 실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @mcp-lens/dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @mcp-lens/dashboard</span></span></code></pre></div><p>start 명령은 자신이 리스닝 중인 주소를 출력한다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MCP Lens dashboard: http://127.0.0.1:43117</span></span></code></pre></div><p>브라우저에서 <code>http://127.0.0.1:43117</code>을 연다. 대시보드는 <code>mcp-lens scan</code>과 훅이 쓰는 것과 같은 <code>~/.mcplens/lens.db</code>를 읽으므로, 이미 수집된 데이터가 있으면 그걸 보여준다. 아직 스캔을 돌리지 않았다면 <a href="/MCPLens/ko/quick-start">빠른 시작</a>을 보고, 매트릭스의 열이 무엇을 뜻하는지는 <a href="/MCPLens/ko/guide/reading-reports">리포트 읽기</a>를 본다.</p><h2 id="알려진-한계" tabindex="-1">알려진 한계 <a class="header-anchor" href="#알려진-한계" aria-label="Permalink to &quot;알려진 한계&quot;">​</a></h2><p>한 번에 하나의 writer만 데이터베이스를 쥘 수 있다. CLI는 <code>~/.mcplens/lens.db</code>에 쓰기 전에 writer lease를 가져가므로, 두 번째 writer(예를 들어 lease를 쥔 VS Code 확장)는 조용히 덮어 쓰이는 대신 깔끔하게 거부당한다. 그래도 CLI와 확장을 같은 데이터베이스에 동시에 돌리는 것은 피한다. 대시보드는 이 데이터베이스를 그대로 읽으므로, <code>scan</code>이 거부되면 실제로 스캔이 성공할 때까지 대시보드는 이전 데이터를 계속 보여준다. 정확한 거부 메시지는 <a href="/MCPLens/ko/faq">FAQ</a>에서 확인한다.</p>`,11)])])}const u=e(d,[["render",n]]);export{k as __pageData,u as default};
